# built by 09-gen_data09.py's own build()), and the fourteen regional encounter tables in 10.10.1's two-sub-table
# shape (threat d20 by relative band 6/11/3 + non-threat d6), audited by PR-10-8 in 13-gen_region.py.

# V(...) mirrors 09_data_adv.V
def V(id, name, arch, band, role, variant="standard", members=1, ctags=(), size=None, attacks=None, powers=(),
      drop_powers=(), abilities=(), gear=None, attrs=None, armor=None, swarm=False, presence=None, pace=None,
      disposition=None, lethal=None, leader=False, depth="walk-on", note=None, place=None):
    return dict(id=id, name=name, arch=arch, band=band, role=role, variant=variant, members=members, ctags=list(ctags),
                size=size, attacks=attacks, powers=list(powers), drop_powers=list(drop_powers), abilities=list(abilities),
                gear=gear, attrs=attrs, armor=armor, swarm=swarm, presence=presence, pace=pace, disposition=disposition,
                lethal=lethal, leader=leader, depth=depth, note=note, place=place)

