# ------------------------------------------------------------------ encounter tables (10.10.1)
# T(range, ref list, rel band, count, **kw) ; NT(range, kind, result, ref=None)
def T(r, ref, band, count="1", ambush=False, complication=False, when="any", note=None, signs=None, terrain=None):
    return dict(range=r, kind="adversary", ref=ref if isinstance(ref, list) else [ref], band=band, count=count, threat=True,
                ambush=ambush, complication=complication, when=when, terrain=terrain, signs=signs, note=note)

def NT(r, kind, result, ref=None):
    d = dict(range=r, kind=kind, result=result, threat=False)
    if ref:
        d["ref"] = ref
    return d

